-- 0.7.0 ADDITIVE migration: audited record corrections (inventory field edits) and a safer NDC rule.
-- Run in the EXISTING D1 Console BEFORE deploying 0.7.0 code. Run each statement once, in order, each as ONE statement.
-- Nothing here deletes or rewrites existing inventory, events, lot_events or adjustments.
-- Corrections never touch scan history: they are an overlay that the inventory view applies, with the original scan values kept.
CREATE TABLE IF NOT EXISTS record_corrections (seq INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL CHECK(kind IN('LOT_GROUP','VIAL')), gtin TEXT NOT NULL CHECK(length(gtin)=14), orig_lot TEXT NOT NULL, orig_expiration TEXT NOT NULL, orig_serial TEXT, field TEXT NOT NULL CHECK(field IN('lot','expiration','serial','scanned_ndc11')), old_value TEXT, new_value TEXT NOT NULL, reason TEXT NOT NULL CHECK(length(reason) BETWEEN 8 AND 500), actor TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')), CHECK((kind='VIAL')=(orig_serial IS NOT NULL)), CHECK(NOT(kind='LOT_GROUP' AND field='serial')), CHECK((field IN('lot','serial') AND length(new_value) BETWEEN 1 AND 20) OR (field='expiration' AND new_value GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]') OR (field='scanned_ndc11' AND length(new_value)=11 AND new_value NOT GLOB '*[^0-9]*')));
CREATE INDEX IF NOT EXISTS record_corrections_lookup ON record_corrections(kind,gtin,orig_lot,orig_expiration,orig_serial,field,seq);
CREATE TRIGGER IF NOT EXISTS record_corrections_validate BEFORE INSERT ON record_corrections BEGIN SELECT RAISE(ABORT,'No such lot group') WHERE NEW.kind='LOT_GROUP' AND NOT EXISTS(SELECT 1 FROM lot_events WHERE gtin=NEW.gtin AND lot=NEW.orig_lot AND expiration=NEW.orig_expiration); SELECT RAISE(ABORT,'No such vial') WHERE NEW.kind='VIAL' AND NOT EXISTS(SELECT 1 FROM events WHERE gtin=NEW.gtin AND serial=NEW.orig_serial); END;
CREATE TRIGGER IF NOT EXISTS record_corrections_no_update BEFORE UPDATE ON record_corrections BEGIN SELECT RAISE(ABORT,'Corrections are append-only'); END;
CREATE TRIGGER IF NOT EXISTS record_corrections_no_delete BEFORE DELETE ON record_corrections BEGIN SELECT RAISE(ABORT,'Corrections are append-only'); END;
-- NDC rule: an NDC may now be edited ONLY while nothing references the library entry. Create the new guard first, then drop the old one.
CREATE TRIGGER IF NOT EXISTS products_identity_guard BEFORE UPDATE ON products WHEN NEW.abc<>OLD.abc OR ((NEW.ndc11<>OLD.ndc11 OR NEW.ndc_original<>OLD.ndc_original) AND (EXISTS(SELECT 1 FROM events WHERE product_abc=OLD.abc) OR EXISTS(SELECT 1 FROM lot_events WHERE product_abc=OLD.abc) OR EXISTS(SELECT 1 FROM package_aliases WHERE product_abc=OLD.abc) OR EXISTS(SELECT 1 FROM gtin_mappings WHERE product_abc=OLD.abc) OR EXISTS(SELECT 1 FROM lot_adjustments WHERE product_abc=OLD.abc))) BEGIN SELECT RAISE(ABORT,'NDC cannot change once inventory, aliases or mappings reference this entry; archive it and add a new entry'); END;
DROP TRIGGER IF EXISTS products_identity_immutable;
-- Verify afterwards: SELECT name FROM sqlite_master WHERE type='trigger' AND (name LIKE 'record_corrections%' OR name LIKE 'products_identity%');
-- Expected: record_corrections_validate, record_corrections_no_update, record_corrections_no_delete, products_identity_guard (and NOT products_identity_immutable).
